SELECT id, product_id, variant_id, media_type, url, thumbnail_url, sort_order, is_main, created_at
FROM product_media WHERE product_id = #{productId}
ORDER BY sort_order ASC, id ASC

SELECT id, product_id, variant_id, media_type, url, thumbnail_url, sort_order, is_main, created_at
FROM product_media WHERE variant_id = #{variantId}
ORDER BY sort_order ASC, id ASC
